function checkCorp(num) {
  const clean = num.replace(/[^0-9]/g, '');
  if (clean.length !== 13) return { valid: false, reason: 'length' };
  const weights = [1, 2, 1, 2, 1, 2, 1, 2, 1, 2, 1, 2];
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += parseInt(clean[i], 10) * weights[i];
  }
  const remainder = sum % 10;
  const checkDigit = (10 - remainder) % 10;
  return {
    valid: checkDigit === parseInt(clean[12], 10),
    calculated: checkDigit,
    actual: parseInt(clean[12], 10),
    court: clean.slice(0, 4),
    kind: clean.slice(4, 6),
    seq: clean.slice(6, 12)
  };
}

